import React from 'react';
import { useAuth } from '../context/AuthContext';
import { Download, Eye, Maximize } from 'lucide-react';

const WeeklyFocus = () => {
    const { user } = useAuth();

    // Use the public URL for the image
    const imageUrl = '/roadmapp.png';

    return (
        <div className="max-w-7xl mx-auto px-4">
            {/* Header */}
            <div className="bg-gradient-to-r from-blue-600 via-purple-600 to-pink-500 rounded-2xl p-6 mb-6 text-white">
                <div className="flex items-center justify-between flex-wrap gap-4">
                    <div>
                        <h1 className="text-2xl md:text-3xl font-bold">
                            🚀 Full Stack + AI Roadmap
                        </h1>
                        <p className="text-blue-100">Your 4-month journey to become a software engineer</p>
                    </div>
                    <div className="flex gap-3">
                        <button 
                            onClick={() => window.open(imageUrl, '_blank')}
                            className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-lg text-sm font-medium transition flex items-center gap-2"
                        >
                            <Eye size={18} />
                            View Full
                        </button>
                        <button 
                            onClick={() => {
                                const link = document.createElement('a');
                                link.href = imageUrl;
                                link.download = 'FullStack_Roadmap.png';
                                link.click();
                            }}
                            className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-lg text-sm font-medium transition flex items-center gap-2"
                        >
                            <Download size={18} />
                            Download
                        </button>
                    </div>
                </div>
            </div>

            {/* Roadmap Image - Full Page View */}
            <div className="bg-white rounded-xl shadow-lg border border-gray-200 p-4 overflow-hidden">
                <img 
                    src={imageUrl}
                    alt="Java Full Stack + AI Engineer Roadmap"
                    className="w-full h-auto rounded-lg"
                    style={{ maxHeight: '80vh', objectFit: 'contain' }}
                    onError={(e) => {
                        console.error('Image failed to load:', imageUrl);
                        e.target.onerror = null;
                        e.target.style.display = 'none';
                        document.getElementById('image-error').style.display = 'block';
                    }}
                />
                <div id="image-error" style={{ display: 'none' }} className="text-center py-20 text-gray-500">
                    <p className="text-xl">⚠️ Image not found</p>
                    <p className="text-sm">Please make sure roadmapp.png is in the public folder</p>
                    <button 
                        onClick={() => window.location.reload()}
                        className="mt-4 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition"
                    >
                        Refresh
                    </button>
                </div>
            </div>

            {/* Full Page Button */}
            <div className="mt-4 flex justify-center">
                <button 
                    onClick={() => window.open(imageUrl, '_blank')}
                    className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-xl font-medium transition flex items-center gap-2 shadow-lg"
                >
                    <Maximize size={20} />
                    View Full Page
                </button>
            </div>

            {/* Footer */}
            <div className="mt-6 text-center text-sm text-gray-400">
                Made by Swaliha • Keep Learning, Keep Growing! 🚀
            </div>
        </div>
    );
};

export default WeeklyFocus;
